// ============================================================
// PARSE FORM v3 — feed_url now optional (from brand_config)
// ============================================================
const form = $input.first().json;

const brandName = (form['Brand Name'] || '').trim();
if (!brandName) throw new Error('Brand Name is required.');

const sheetUrl = form['Data Sheet URL (Google Sheets)'] || '';
const sheetIdMatch = sheetUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
const sheetId = sheetIdMatch ? sheetIdMatch[1] : '';
if (!sheetId) throw new Error('Invalid Google Sheet URL.');

const now = new Date();
const y1ago = new Date(now);
y1ago.setFullYear(y1ago.getFullYear() - 1);

return [{ json: {
  _brand_name: brandName,
  _brand_key: brandName.toLowerCase(),
  _feed_url: (form['Feed URL (XML) — opcjonalne, nadpisuje brand_config'] || '').trim(),
  _sheet_id: sheetId,
  _date_from: (form['Date From (YYYY-MM-DD)'] || '').trim() || y1ago.toISOString().split('T')[0],
  _date_to: (form['Date To (YYYY-MM-DD)'] || '').trim() || now.toISOString().split('T')[0],
  _form_ga4_id: (form['GA4 Property ID (opcjonalne)'] || '').trim(),
  _form_meta_id: (form['Meta Account ID (opcjonalne)'] || '').trim()
} }];

// ============================================================
// BUILD CONFIG v4 — feed_url from brand_config, form = override
// ============================================================

const formData = $node['Parse Form'].json;

const HARDCODED = {
  'iiyama':      { ga4: '280127077',  meta: 'act_1438113836305522' },
  'bushido':     { ga4: '297192186',  meta: 'act_1930400651212132' },
  'koszulkowy':  { ga4: '270928705',  meta: 'act_1897121353740892' },
  'mindlink':    { ga4: '477769901',  meta: 'act_1578563932814949' }
};

const sheetBrands = $input.all().map(i => i.json);
const sheetMatch = sheetBrands.find(row =>
  (row.brand_name || '').toLowerCase().trim() === formData._brand_key
);

if (!sheetMatch) {
  throw new Error(`❌ Brand "${formData._brand_name}" nie znaleziony w brand_config. Dodaj wiersz z brand_name="${formData._brand_name}".`);
}

const vatRate = parseFloat(sheetMatch.vat_rate) || 0.23;

const hardcoded = HARDCODED[formData._brand_key];
const ga4Id = formData._form_ga4_id
           || String(sheetMatch.ga4_property_id || '')
           || (hardcoded ? hardcoded.ga4 : '');
const metaId = formData._form_meta_id
            || String(sheetMatch.meta_account_id || '')
            || (hardcoded ? hardcoded.meta : '');

// feed_url: form override → brand_config → error
const feedUrl = formData._feed_url
             || (sheetMatch.feed_url || '').trim();

return [{ json: {
  BRAND: formData._brand_name,
  VAT_RATE: vatRate,
  FEED_URL: feedUrl,
  SHEET_ID: formData._sheet_id,
  GA4_PROPERTY_ID: String(ga4Id).replace(/\.0$/, ''),
  META_ACCOUNT_ID: String(metaId),
  DATE_FROM: formData._date_from,
  DATE_TO: formData._date_to,
  MSC_ALGO: { MIN_META_TRANS: 10, MIN_ORGANIC_SESSIONS: 300 }
} }];

// ============================================================
// MARGIN RESOLVER v2 — Supports DEFAULT rule type
// ============================================================

const rules = $input.all().map(item => ({
  match_type:  (item.json.match_type  || '').toUpperCase().trim(),
  match_value: (item.json.match_value || '').trim(),
  margin_rate: parseFloat(item.json.margin_rate) || 0
}));

const validTypes = ['SKU_EXACT', 'CATEGORY_EXACT', 'KEYWORD', 'DEFAULT'];
const validRules = rules.filter(r => validTypes.includes(r.match_type) && r.margin_rate > 0);

// Extract DEFAULT rule for fallback (separate from matching rules)
const defaultRule = validRules.find(r => r.match_type === 'DEFAULT');
const matchingRules = validRules.filter(r => r.match_type !== 'DEFAULT');

const config = $node['Build Config'].json;

// If DEFAULT rule exists in sheet, it overrides config DEFAULT_MARGIN
const effectiveDefault = defaultRule ? defaultRule.margin_rate : config.DEFAULT_MARGIN;

return [{ json: {
  ...config,
  DEFAULT_MARGIN: effectiveDefault,
  MARGIN_RULES: matchingRules,
  MARGIN_RULES_COUNT: matchingRules.length,
  _has_default_rule: !!defaultRule,
  _resolver_executed: true
} }];

// NORMALIZE FEED + MARGINS v3
// FIX: g: namespace fields use bracket notation (p['g:id'] not p.g_id)
// FIX: DEFAULT rule from margin_rules is used as fallback
// ADD: feed_image_link extraction (Issue 2)
const config = $node['Validate Config'].json;
const marginRules = config.MARGIN_RULES || [];
const defaultMargin = config.DEFAULT_MARGIN || 0.10;

function normalizeUrl(url) {
  if (!url) return '';
  let u = url.toLowerCase().replace(/^https?:\/\/(www\.)?/, '').split('?')[0].replace(/\/$/, '');
  return u;
}

function resolveMargin(feedId, feedCategory, feedTitle) {
  const id = (feedId || '').trim();
  const cat = (feedCategory || '').toLowerCase().trim();
  const title = (feedTitle || '').toLowerCase().trim();
  const searchStr = cat + ' ' + title;
  for (const rule of marginRules) {
    if (rule.match_type === 'SKU_EXACT' && id === rule.match_value) return rule.margin_rate;
    if (rule.match_type === 'CATEGORY_EXACT' && cat === rule.match_value.toLowerCase()) return rule.margin_rate;
    if (rule.match_type === 'KEYWORD' && searchStr.includes(rule.match_value.toLowerCase())) return rule.margin_rate;
  }
  return defaultMargin;
}

const feedData = $input.first().json;
let products = [];
if (feedData.rss?.channel?.item) products = [feedData.rss.channel.item].flat();
else if (feedData.feed?.entry) products = [feedData.feed.entry].flat();
else if (feedData.products?.product) products = [feedData.products.product].flat();

return products.map(p => {
  const id = p['g:id'] || p.g_id || p.id || '';
  const cat = p['g:product_type'] || p['g:google_product_category'] || p.product_type || p.google_product_category || '';
  const link = p['g:link'] || p.g_link || p.link || '';
  const priceRaw = p['g:price'] || p.g_price || p.price || '0';
  const title = p['g:title'] || p.g_title || p.title || '';
  const brand = p['g:brand'] || p.g_brand || p.brand || '';
  const imageLink = p['g:image_link'] || p.g_image_link || p.image_link || '';

  return { json: {
    feed_id: id,
    feed_title: title,
    feed_brand: brand,
    feed_price: parseFloat(String(priceRaw).replace(/[^0-9.]/g, '')) || 0,
    feed_category: cat,
    feed_link: link,
    feed_image_link: imageLink,
    norm_url_path: normalizeUrl(link).split('/').slice(1).join('/'),
    base_gross_margin: resolveMargin(id, cat, title)
  }};
});

// NORMALIZE GA4 LP (null-safe)
const response = $input.first().json;
const rows = response.rows || [];
if (rows.length === 0) {
  console.log('WARNING: GA4 LP returned 0 rows — filter may be too strict or property ID wrong');
  return [{ json: { ga4_lp_url: '', ga4_sessions: 0, ga4_revenue: 0, ga4_trans: 0, ga4_users: 0, ga4_first_time_purchasers: 0, _empty: true } }];
}
return rows.map(row => {
  const lp = row.dimensionValues[0].value || '';
  return { json: {
    ga4_lp_url: lp,
    ga4_norm_path: lp.toLowerCase().replace(/^\/|\/$/g, '').split('?')[0],
    ga4_sessions: parseInt(row.metricValues[0].value),
    ga4_revenue: parseFloat(row.metricValues[1].value),
    ga4_trans: parseInt(row.metricValues[2].value),
    ga4_users: parseInt(row.metricValues[3].value),
    ga4_first_time_purchasers: parseInt(row.metricValues[4].value)
  }};
});

// NORMALIZE GA4 ITEMS (null-safe)
const response = $input.first().json;
const rows = response.rows || [];
if (rows.length === 0) {
  console.log('WARNING: GA4 Items returned 0 rows');
  return [{ json: { ga4_item_id: '', ga4_item_views: 0, ga4_item_rev: 0, ga4_item_purch: 0, _empty: true } }];
}
return rows.map(row => {
  return { json: {
    ga4_item_id: row.dimensionValues[0].value,
    ga4_item_views: parseInt(row.metricValues[0].value),
    ga4_item_rev: parseFloat(row.metricValues[1].value),
    ga4_item_purch: parseInt(row.metricValues[2].value)
  }};
});

// NORMALIZE META ADS
const data = $input.first().json.data || [];
return data.map(ad => {
  const getVal = (list, type) => {
    if (!list) return 0;
    const m = list.find(x => x.action_type === type);
    return m ? parseFloat(m.value) : 0;
  };
  const purch = getVal(ad.actions, 'offsite_conversion.fb_pixel_purchase') || getVal(ad.actions, 'purchase');
  const val = getVal(ad.action_values, 'offsite_conversion.fb_pixel_purchase') || getVal(ad.action_values, 'purchase');
  const spend = parseFloat(ad.spend || '0');

  return { json: {
    meta_ad_id: ad.ad_id,
    meta_ad_name: ad.ad_name,
    meta_url: ad.website_url || '',
    meta_spend: spend,
    meta_purch: purch,
    meta_rev: val,
    meta_roas: spend > 0 ? val / spend : 0
  }};
});

// ============================================================
// PYTHON BRIDGE — Consolidate all data for external Python API
// ============================================================

const warnings = [];
const safeGet = (nodeName) => {
  try {
    const items = $(nodeName).all().map(i => i.json);
    if (items.length === 0) warnings.push(nodeName + ': 0 items');
    return items;
  } catch (e) {
    warnings.push(nodeName + ' FAILED: ' + e.message);
    return [];
  }
};

const feed = safeGet('Normalize Feed + Margins');
const meta = safeGet('Normalize Meta Ads');
const items = safeGet('Normalize GA4 Items');
const lp = safeGet('Normalize GA4 LP');

let config = {};
try { config = $('Margin Resolver').first().json; } catch(e) {}

// Log data sizes for debugging
console.log('Python Bridge: feed=' + feed.length + ', meta=' + meta.length + ', items=' + items.length + ', lp=' + lp.length);
if (warnings.length > 0) console.log('WARNINGS: ' + warnings.join('; '));

// Return consolidated payload as single item
return [{ json: {
  feed: feed,
  meta_ads: meta,
  ga4_items: items,
  ga4_lp: lp,
  _debug: { feed: feed.length, meta: meta.length, items: items.length, lp: lp.length, warnings: warnings, date_from: config.DATE_FROM, date_to: config.DATE_TO },
  config: {
    brand: config.BRAND || '',
    vat_rate: config.VAT_RATE || 0.23,
    default_margin: config.DEFAULT_MARGIN || 0.10,
    margin_rules: config.MARGIN_RULES || []
  }
} }];

// ============================================================
// PARSE API RESPONSE
// Ensures Python API response is properly formatted for Sheets
// ============================================================
const items = $input.all().map(i => i.json);

// Handle case where response is nested in 'data' or similar
if (items.length === 1 && Array.isArray(items[0])) {
  return items[0].map(item => ({ json: item }));
}

// Already properly formatted
return items.map(item => ({ json: item }));

// ============================================================
// VALIDATE CONFIG — Pre-flight checks before API calls
// ============================================================
const c = $input.first().json;
const errors = [];
const warnings = [];

// 1. Brand
if (!c.BRAND) errors.push('❌ Nazwa brandu jest pusta');

// 2-3. Feed URL
if (!c.FEED_URL) errors.push('❌ Feed URL jest pusty — dodaj feed_url do brand_config lub wpisz w formularzu');
else if (!c.FEED_URL.startsWith('http')) errors.push('❌ Feed URL musi zaczynać się od http:// lub https://');
else if (!c.FEED_URL.includes('.xml') && !c.FEED_URL.includes('feed')) warnings.push('⚠️ Feed URL nie zawiera .xml ani feed — upewnij się, że to feed produktowy');

// 4-5. GA4
if (!c.GA4_PROPERTY_ID) errors.push('❌ GA4 Property ID jest pusty — uzupełnij w brand_config lub formularzu');
else if (/[^0-9]/.test(String(c.GA4_PROPERTY_ID))) errors.push('❌ GA4 Property ID powinien zawierać tylko cyfry, otrzymano: ' + c.GA4_PROPERTY_ID);

// 6-7. Meta
if (!c.META_ACCOUNT_ID) errors.push('❌ Meta Account ID jest pusty — uzupełnij w brand_config lub formularzu');
else if (!String(c.META_ACCOUNT_ID).startsWith('act_')) errors.push('❌ Meta Account ID powinien zaczynać się od act_, otrzymano: ' + c.META_ACCOUNT_ID);

// 8-9. VAT
if (!c.VAT_RATE || c.VAT_RATE === 0) errors.push('❌ Brak stawki VAT w brand_config');
else if (c.VAT_RATE > 1) warnings.push('⚠️ VAT_RATE = ' + c.VAT_RATE + ' — czy chodziło o ' + (c.VAT_RATE / 100).toFixed(2) + '?');

// 10-12. Dates
const from = new Date(c.DATE_FROM);
const to = new Date(c.DATE_TO);
if (from > to) errors.push('❌ Data początkowa (' + c.DATE_FROM + ') jest późniejsza niż końcowa (' + c.DATE_TO + ')');
const daysDiff = Math.floor((to - from) / 86400000);
if (daysDiff > 730) warnings.push('⚠️ Zakres dat = ' + daysDiff + ' dni (> 2 lata) — może zwrócić za dużo danych');
if (daysDiff < 7) warnings.push('⚠️ Zakres dat = ' + daysDiff + ' dni (< 7) — za mało danych do rzetelnej klasyfikacji');

// 13. Margin Rules
if (!c.MARGIN_RULES || c.MARGIN_RULES.length === 0) warnings.push('⚠️ Brak reguł marżowych w margin_rules — wszystko dostanie domyślną marżę');

// 14. Sheet ID
if (!c.SHEET_ID) errors.push('❌ Brak ID arkusza Google Sheets');

// Log warnings
if (warnings.length > 0) console.log('VALIDATION WARNINGS:\n' + warnings.join('\n'));

// Block on errors
if (errors.length > 0) {
  throw new Error('VALIDATION FAILED:\n\n' + errors.join('\n') + (warnings.length > 0 ? '\n\n' + warnings.join('\n') : ''));
}

return [{ json: { ...c, _validation: 'PASSED', _warnings: warnings } }];
